def teaching_for(code: str):
    """Fail closed if any upstream semantic category is missing."""
    if code in FAMILY_OVERRIDES:
        return FAMILY_OVERRIDES[code]
    key = code if code in SEMANTICS else code[:2]
    return SEMANTICS[key]
